function Icon({ name, className = "" }: { name: string; className?: string }) { return <span aria-hidden="true" className={`icon ${className}`}>{iconMap[name] ?? "•"}</span>; }

async function requestJson<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, { ...options, headers: { "Content-Type": "application/json", ...(options?.headers ?? {}) } });
  const contentType = response.headers.get("content-type") || "";
  const data = contentType.includes("application/json") ? await response.json().catch(() => ({})) : {};
  if (!response.ok) throw new Error((data as { error?: string }).error || "Something went wrong.");
  return data as T;
}

