function AuthScreen({ mode, setMode, onSuccess }: { mode: "login" | "signup"; setMode: (mode: "login" | "signup") => void; onSuccess: (user: User) => void }) {
  const [isRecovery, setRecovery] = useState(false); const [username, setUsername] = useState(""); const [password, setPassword] = useState(""); const [matriculationNumber, setMatriculationNumber] = useState(""); const [newPassword, setNewPassword] = useState(""); const [confirmPassword, setConfirmPassword] = useState(""); const [available, setAvailable] = useState<boolean | null>(null); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  useEffect(() => { if (mode === "signup" && username.length >= 3) { const timer = setTimeout(() => requestJson<{ available: boolean }>(`/api/auth/availability?username=${encodeURIComponent(username)}`).then((data) => setAvailable(data.available)).catch(() => setAvailable(null)), 250); return () => clearTimeout(timer); } setAvailable(null); }, [username, mode]);
  async function submit(e: FormEvent) { e.preventDefault(); setError(""); if (mode === "signup" && password !== confirmPassword) { setError("Passwords do not match."); return; } setLoading(true); try { const data = isRecovery ? await requestJson<{ user: User }>("/api/auth/recover", { method: "POST", body: JSON.stringify({ username, matriculationNumber, newPassword }) }) : await requestJson<{ user: User }>(`/api/auth/${mode === "login" ? "login" : "register"}`, { method: "POST", body: JSON.stringify({ username, password, matriculationNumber }) }); onSuccess(data.user); } catch (e) { setError(e instanceof Error ? e.message : "Unable to continue."); } finally { setLoading(false); } }
  return <div className="auth-page"><div className="auth-visual"><div className="auth-visual-top"><Logo dark/><span>Student learning space</span></div><div className="auth-visual-copy"><div className="eyebrow">FOCUS ON THE NEXT STEP</div><h1>Make every study hour count.</h1><p>Summaries, past questions and progress — organised around the courses you care about.</p></div><div className="auth-quote"><span>“</span><p>NounStudyHub makes revision feel less overwhelming. I finally know what to study next.</p><small>— A focused NOUN student</small></div><div className="auth-visual-footer"><span>01 / 03</span><div><i/><i/><i/></div></div></div><div className="auth-form-side"><button className="back-button" onClick={() => setMode("login")}><Icon name="arrow"/> Back to home</button><div className="auth-form-wrap"><div className="auth-mobile-logo"><Logo/></div>{isRecovery ? <><div className="auth-kicker">ACCOUNT RECOVERY</div><h2>Reset your password.</h2><p className="auth-sub">Use your username and matriculation number to get back in.</p></> : <><div className="auth-kicker">{mode === "login" ? "WELCOME BACK" : "GET STARTED"}</div><h2>{mode === "login" ? "Welcome back." : "Create your account."}</h2><p className="auth-sub">{mode === "login" ? "Your next focused session is waiting." : "Join thousands of students studying with purpose."}</p></>}
    <form onSubmit={submit} className="auth-form"><label>Username<input autoComplete="username" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="e.g. Khalifa" required/>{mode === "signup" && username.length >= 3 && <span className={`availability ${available ? "yes" : "no"}`}>{available ? "✓ Username available" : "× Username already taken"}</span>}</label>{mode === "signup" && <><label>Password<input type="password" autoComplete="new-password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="At least 8 characters" required/><span className="password-rule">Use at least 8 characters</span></label><label>Confirm password<input type="password" autoComplete="new-password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Re-enter your password" required/>{password && confirmPassword && <span className={`availability ${password === confirmPassword ? "yes" : "no"}`}>{password === confirmPassword ? "✓ Passwords match" : "× Passwords do not match"}</span>}</label><label>Matriculation number<input value={matriculationNumber} onChange={(e) => setMatriculationNumber(e.target.value)} placeholder="e.g. Nou123456789" required/></label></>}{mode === "login" && <label>Password<input type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Your password" required/></label>}{isRecovery && <><label>Matriculation number<input value={matriculationNumber} onChange={(e) => setMatriculationNumber(e.target.value)} placeholder="e.g. Nou123456789" required/></label><label>New password<input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} placeholder="Create a new password" required/></label></>}{error && <div className="form-error"><Icon name="close"/> {error}</div>}<Button type="submit" className="full-button" disabled={loading}>{loading ? "Please wait…" : isRecovery ? "Reset password" : mode === "login" ? "Log in to NounStudyHub" : "Create my account"}<Icon name="arrow"/></Button></form>
    <div className="auth-switch">{mode === "login" && !isRecovery && <button onClick={() => setRecovery(true)}>Forgot password?</button>}<p>{isRecovery ? "Remembered your password?" : mode === "login" ? "New to NounStudyHub?" : "Already have an account?"} <button onClick={() => { setRecovery(false); setMode(mode === "login" ? "signup" : "login"); }}>{isRecovery ? "Log in" : mode === "login" ? "Create an account" : "Log in"}</button></p></div></div><div className="auth-help">By continuing, you agree to our <a href="/terms">Terms of use</a> and <a href="/privacy">Privacy policy</a>.</div></div></div>;
}

